namespace Obozny;

/// <summary>Повний розгорнутий текст умов бети (має вимагати довгого скролу).</summary>
internal static class BetaTermsText
{
    public static IReadOnlyList<(string Heading, string Body)> Sections { get; } =
    [
        ("Що таке Обозний",
            "Обозний — програма початкового рівня обліку майна у військовій частині. Призначена насамперед для сержантів з МТЗ та інших посадових осіб, які ведуть первинний облік на складі підрозділу, в опорному пункті чи на аналогічному місці зберігання. Програма не замінює штатні облікові системи вищого рівня й не претендує на роль єдиного джерела істини для всієї військової частини: це робочий інструмент «на землі», щоб швидко бачити залишки, рух і основні документи.\n\n" +
            "Зараз програма фіксує облік: що є на складі, у якій кількості, може розділяти основні засоби та запаси, вести облік опорних пунктів. Користувач може переглядати таблиці залишків і руху, відкривати картки майна, працювати з номенклатурою, формувати чернетки документів і проводити їх у локальній базі даних програми.\n\n" +
            "За допомогою Обозного можна завантажити (імпортувати) документи щодо руху майна (накладні, Акти ПП, Акти списання тощо), щоб не вводити їх вручну рядок за рядком, а також створювати деякі робочі та службові документи (паспорти опорних пунктів, формуляри інженерних загороджень, Акти ВР та ЯС тощо). Окремо доступний експорт залишків або руху майна в електронну таблицю для подальшої роботи поза програмою.\n\n" +
            "Типовий сценарій використання: сержант з МТЗ відкриває Обозний на початку зміни, звіряє залишки з фактичним станом, імпортує або вводить документи руху, проводить внутрішні акти, за потреби експортує таблицю для доповіді. Уся робота йде локально на комп’ютері користувача; програма не вимагає постійного підключення до мережі для обліку.\n\n" +
            "Обмеження початкового рівня означають, що частина складних облікових процедур, інтеграцій і регламентів вищого рівня може бути відсутня або спрощена. Якщо ваша частина вже має обов’язкову корпоративну систему обліку — Обозний використовуйте лише в межах повноважень і внутрішніх правил підрозділу, не підміняючи офіційний облік там, де це заборонено."),

        ("Автор і права на програму",
            "Автором є Дмитро КРАМАРЕНКО, діючий військовослужбовець, позивний Сталкер, і є відкритим розробником, що створює програму у позаслужбовий час. Комп’ютерна програма з моменту створення коду є об’єктом авторського права автора (літературний твір у розумінні Цивільного кодексу України).\n\n" +
            "Зв’язок користувачів із автором щодо виправлень і оновлень здійснюється лише в межах загального плану чергових оновлень версій програми, без зобов’язання миттєвої індивідуальної підтримки. Автор може враховувати звернення при плануванні наступних збірок, але не гарантує відповіді в конкретний строк, виправлення конкретної помилки «на вчора» чи персонального супроводу підрозділу.\n\n" +
            "Користувач не отримує права змінювати, декомпілювати чи поширювати програму способами, що порушують авторське право, якщо окремо не надано письмового дозволу автора або іншої підстави, передбаченої законом. Дозволене використання бета-версії описане в цих умовах і стосується ознайомлення, тестування та практичної перевірки на локальному робочому місці.\n\n" +
            "Назва «Обозний», інтерфейс, структура даних і супровідні матеріали, що входять у поставку, також охороняються в межах прав автора на відповідні об’єкти. Використання назви чи матеріалів програми в публічних матеріалах бажано погоджувати з автором, якщо це виходить за межі внутрішнього службового обігу підрозділу."),

        ("Бета та ліцензія",
            "Обозний надається як бета-версія для тестування. Поширюється безоплатно на умовах «як є» (AS IS), виключно з метою ознайомлення та перевірки, без гарантій щодо безперебійної роботи чи повної відповідності вашим потребам.\n\n" +
            "Бета означає, що функції можуть змінюватися, з’являтися або зникати між збірками; можливі помилки імпорту, відображення, проведення документів чи сумісності з певними файлами Excel. Користувач зобов’язаний самостійно робити резервні копії даних (зокрема файлу обліку програми) перед масовим імпортом і перед оновленням збірки.\n\n" +
            "Фінальна версія може поширюватися на інших умовах і вимагатиме окремої ліцензії (у тому числі платної) згідно з умовами на момент релізу. Безоплатне розповсюдження бети не є комерційною діяльністю і не створює зобов’язань розробника перед користувачем щодо строків доопрацювання, обсягу функцій чи сумісності зі стороннім ПЗ.\n\n" +
            "Приймаючи ці умови, ви підтверджуєте, що розумієте характер бета-версії: це тестова поставка, а не гарантований промисловий продукт із договором рівня SLA. Якщо для вашого підрозділу критична безперервність обліку — плануйте паралельний контроль (паперові журнали, штатні системи, періодичні звірки) на період тестування.\n\n" +
            "Автор залишає за собою право змінювати умови поширення наступних версій, припиняти бета-доступ через оновлення програми (зокрема шляхом обмеження імпорту/експорту після закінчення строку) і вимагати обов’язкового оновлення для повного зняття обмежень."),

        ("Термін бета-доступу (3 місяці)",
            "Строк бета-доступу — 3 місяці з дати першого прийняття цих умов на даному комп’ютері. Дата першого прийняття фіксується програмою разом із підписаною міткою; просте змінення дати в файлі налаштувань не продовжує строк і може бути розцінене як порушення цілісності мітки доступу.\n\n" +
            "За 14 днів до закінчення строку програма попередить при запуску, скільки днів лишилось. Після закінчення строку обмежуються лише імпорт та експорт документів. Додавання майна через форму, створення й проведення внутрішніх документів залишаються доступними, щоб підрозділ не втратив можливість вести базовий облік вручну.\n\n" +
            "Повне зняття обмежень можливе лише після обов’язкового оновлення програми до нової версії, яку надає автор (або інший уповноважений канал поширення). Скидання прапорця згоди в файлі даних, підстановка «сьогоднішньої» дати чи видалення окремих полів налаштувань не призначені для отримання нового тримісячного циклу.\n\n" +
            "Якщо мітку прийняття пошкоджено, підроблено або розсинхронізовано з підписом, програма розглядає бета-доступ як закінчений і застосовує ті самі обмеження імпорту/експорту, що й після закінчення календарного строку. Це зроблено навмисно, щоб захистити чесний тестовий період і стимуливати перехід на актуальну збірку.\n\n" +
            "Повторне відкриття цього вікна після першого «Погоджуюсь» не перезапускає відлік. Перше прийняття на машині є остаточним стартом тримісячного вікна для цієї інсталяції бети."),

        ("Відкриті дані та ДСК",
            "У логіці програми використовуються лише відкриті відомості (формули, відкриті норми, загальні правила обліку в межах функцій програми). Програма не містить у коді закритих нормативів із грифом секретності й не розрахована на автоматичну класифікацію документів за грифом.\n\n" +
            "Фактично програма є хорошим калькулятором чи дуже модернізованою електронною таблицею, яка дозволяє створювати різні документи, у тому числі ті, що містять службову інформацію. Відповідальність за введення та обробку даних з грифом ДСК (для службового користування) лежить на користувачі та посадових особах, які допустили обробку на конкретному робочому місці.\n\n" +
            "Обробка таких даних дозволена лише на атестованих комп’ютерах згідно з Постановою КМУ №1392 та іншими чинними вимогами щодо захисту інформації. З урахуванням того, що для роботи програми не потрібен Інтернет і вона нічого не передає в мережу Інтернет, використання атестованих для ДСК комп’ютерів є цілком можливим — за умови дотримання внутрішніх процедур частини.\n\n" +
            "Користувач зобов’язаний не експортувати й не переносити файли з чутливими даними на носії чи в середовища, де це заборонено режимом секретності / ДСК. Автор програми не контролює зміст введених даних і не несе відповідальності за порушення режиму доступу з боку користувача.\n\n" +
            "Якщо ви сумніваєтесь, чи дозволено вести конкретний облік у Обозному на вашому ПК — зверніться до посадової особи, відповідальної за захист інформації у підрозділі, до введення реальних даних."),

        ("Офлайн, без передачі в інтернет",
            "Програма не має вбудованих функцій передачі ваших файлів чи даних обліку на зовнішній сервер через мережу Інтернет. Дані зберігаються локально на вашому комп’ютері (у файлі обліку поруч із програмою або в каталозі робочої копії).\n\n" +
            "Відсутність телеметрії й «хмари» не скасовує ризиків, якщо сам користувач копіює файли на мережеві диски, надсилає їх поштою чи синхронізує через сторонні служби. Такі дії — поза межами поведінки програми і повністю на відповідальності користувача.\n\n" +
            "Оновлення бети, якщо вони надаються, користувач встановлює самостійно (заміна exe / поставки), без автоматичного завантаження з мережі всередині цієї збірки. Умови саме цієї бета-збірки не передбачають вбудованого інсталятора оновлень «по кнопці з інтернету».\n\n" +
            "Рекомендується періодично копіювати каталог із даними (зокрема obozny.json і бекапи) на захищений носій згідно з правилами підрозділу, щоб не втратити облік при поломці диска."),

        ("Захист при роботі з документами",
            "Формування документів (зокрема PDF, Excel) виконується в оперативній пам’яті, без створення зайвих тимчасових файлів на диску там, де це реалізовано в програмі. Це зменшує ризик «хвостів» із чутливими даними в каталогах TEMP, але не замінює дисципліну користувача щодо збережених вами файлів експорту.\n\n" +
            "Передбачено заходи проти підміни бібліотек програми шкідливим кодом у межах можливостей локальної поставки. Водночас користувач має запускати лише збірки, отримані з довіреного джерела автора / підрозділу, і не підкладати сторонні DLL у каталог програми.\n\n" +
            "Якщо антивірус або політики безпеки блокують запуск — погодьте виняток у встановленому порядку, не вимикаючи захист системи цілком. Автор не просить і не рекомендує вимикати захист ОС ради зручності.\n\n" +
            "Після експорту документа на диск файл стає звичайним файлом ОС: його подальше копіювання, друк і передача регулюються вашими внутрішніми правилами, а не Обозним."),

        ("Апаратна ізоляція (за наявності в поставці)",
            "Разом із програмою може постачатися скрипт Block_Internet.bat. Його запуск від імені адміністратора перед використанням прописує правила брандмауера Windows, що блокують програмі мережевий трафік для самої програми — додатковий бар’єр навіть якщо комп’ютер підключено до Інтернету. При цьому доступ до Інтернету для інших програм — не обмежується.\n\n" +
            "Скрипт є допоміжним засобом і не входить обов’язково в кожну поставку. Якщо скрипта немає — це не означає, що програма «ходить в інтернет»: убудованої передачі обліку немає. Скрипт лише підсилює ізоляцію на рівні ОС.\n\n" +
            "Неправильне застосування правил брандмауера може зачепити інші ярлики з тією ж назвою exe. Запускайте скрипт лише для тієї копії Обозного, яку реально використовуєте, і за потреби звертайтесь до системного адміністратора підрозділу.\n\n" +
            "Видалення правил брандмауера після тестування — відповідальність користувача/адміністратора; автор не гарантує автоматичного відкату політик."),

        ("Поширення, копії та підрозділи",
            "Бета-версію дозволено встановлювати на робочих місцях підрозділу для тестування в межах цих умов. Передача копії іншому підрозділу не знімає обов’язку кожного користувача прийняти умови при першому запуску на своїй машині й не продовжує строк бети «через чуже прийняття».\n\n" +
            "Не дозволяється видавати бету за офіційний продукт Міноборони, Генштабу чи іншої установи, якщо такого статусу програмі не надано окремим рішенням. Не дозволяється вимагати оплату «за ліцензію бети» від кінцевих користувачів від імені автора, якщо автор цього не уповноважував.\n\n" +
            "Для підрозділів Збройних Сил України може передбачатися безоплатне надання ліцензій фінальної версії (без виплати винагороди дистриб’ютору) — згідно з окремими умовами поширення фінальної версії на момент релізу. Ці умови бети не є договором поставки фінальної ліцензії й не фіксують ціну чи строк майбутнього релізу.\n\n" +
            "Якщо ви отримали програму через посередника, перевіряйте цілісність файлу і джерело. Автор відповідає лише за збірки, які сам поширює або прямо підтверджує."),

        ("Відповідальність і ризики",
            "Програма надається без гарантій. Автор не відшкодовує збитки від втрати даних, простою, помилкового проведення документів, несумісності з файлами сторонніх систем чи дій користувача, якщо інше не передбачено окремим письмовим договором.\n\n" +
            "Користувач сам перевіряє результати імпорту й проведення перед тим, як спиратися на них у службових рішеннях. Рекомендується вибіркова звірка з первинними документами на папері чи в іншій системі.\n\n" +
            "У разі виявлення критичної помилки бажано зберегти копію даних і опис кроків відтворення; автор може використати це при плануванні виправлень, але не зобов’язаний надати індивідуальний патч поза загальним графіком оновлень.\n\n" +
            "Ці умови не обмежують права споживача чи інші імперативні норми закону там, де вони застосовуються й не можуть бути змінені угодою сторін."),

        ("Прийняття умов",
            "Натискаючи «Погоджуюсь», ви підтверджуєте, що ознайомлені з цими умовами, прокрутили текст до кінця, розумієте характер бета-версії, тримісячний строк доступу, подальші обмеження імпорту/експорту та відповідальність за дані, які вводите.\n\n" +
            "Кнопка «Погоджуюсь» активується лише після прокрутки тексту до самого низу. Кнопка «Вийти» доступна завжди: у такому разі програма завершує роботу без прийняття умов і без запису старту бета-строку.\n\n" +
            "Після прийняття умови вважаються прийнятими для цієї інсталяції; подальше використання програми означає дотримання викладених тут правил до оновлення на іншу версію з новими умовами."),
    ];
}
